targets.expr:
topk(
  200,
  max by (normalized_event_id, client_mac, ssid, controller_timestamp_ms, parse_status) (
    max_over_time(
      {job="omada_webhook_normalized",event="omada.client_offline"} | json | client_mac!="" | client_mac!~"${exclude_noisy_mac:raw}" | client_mac=~"${client_mac:raw}" | ssid=~"${traffic_ssid:raw}" | reported_traffic_bytes_estimate >= 0
      | controller_timestamp_ms > 0
      | reported_traffic_bytes_estimate >= ${traffic_watch_session_min_bytes:raw}
      | unwrap reported_traffic_bytes_estimate
      | __error__=""
      [$__range]
    )
  )
)
